"""All texts of MyTV: generates res/values*/strings.xml, so every language has every key.

    python tools/strings.py            (writes android/app/src/main/res)

The table below has the source texts: en (default and fallback), nl, fr, de, es, pt (Portugal). Every other language
is one file in tools/strings/<language tag>.json ({"_tag", "_name", "strings": {key: text}, "arrays": {...}}), checked
here against the English keys and placeholders. Add or change a text in the table, run this, and commit both; a new
key must also be added to every JSON file (the run stops and lists what is missing).
A text ending in _sub is the one-line explanation under a setting: keep it short enough for one line on a 1080p TV
(tools/check_subtitles.py measures them, in every language).
"""
import sys, os
RES = sys.argv[1] if len(sys.argv) > 1 else os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'android', 'app', 'src', 'main', 'res')
L = ['en', 'nl', 'fr', 'de', 'es', 'pt']
