ARR = {
'wind_dirs': [['N','NE','E','SE','S','SW','W','NW'], ['N','NO','O','ZO','Z','ZW','W','NW'], ['N','NE','E','SE','S','SO','O','NO'],
              ['N','NO','O','SO','S','SW','W','NW'], ['N','NE','E','SE','S','SO','O','NO'], ['N','NE','L','SE','S','SO','O','NO']],
}
def esc(v):
    v = v.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace("'", "\\'").replace('"', '\\"')
    if v.startswith('@') or v.startswith('?'): v = '\\' + v
    return v

import json, re
# Android resource folders for language tags (Android still uses the old codes for Indonesian and Hebrew).
QUALIFIER = {'en': '', 'id': 'in', 'he': 'iw', 'pt-BR': 'pt-rBR', 'zh-CN': 'zh-rCN', 'zh-TW': 'zh-rTW'}
EXTRA = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'strings')

def placeholders(v): return sorted(re.findall(r'%\d+\$[sd]|%\d+\$\.\d+f|%[sd]', v))

def languages():
    """(tag, {key: text}, {array: [items]}) for every language: the table's six, then the JSON files."""
    for i, lang in enumerate(L):
        for k, vals in S.items(): assert len(vals) == 6, k
        yield lang, {k: v[i] for k, v in S.items()}, {k: v[i] for k, v in ARR.items()}
    problems = []
    for f in sorted(os.listdir(EXTRA)) if os.path.isdir(EXTRA) else []:
        if not f.endswith('.json'): continue
        t = json.load(open(os.path.join(EXTRA, f), encoding='utf-8'))
        tag, got, arr = t['_tag'], t['strings'], t['arrays']
        assert f == tag + '.json', f
        problems += [f'{tag}: missing {k}' for k in S if k not in got] + [f'{tag}: unknown {k}' for k in got if k not in S]
        problems += [f'{tag}: placeholders of {k}' for k in S if k in got and placeholders(got[k]) != placeholders(S[k][0])]
        problems += [f'{tag}: array {k}' for k in ARR if len(arr.get(k, [])) != len(ARR[k][0])]
        yield tag, got, arr
    if problems: sys.exit('\n'.join(problems))

if __name__ == '__main__':
    all_langs = list(languages())
    for lang, texts, arrays in all_langs:
        q = QUALIFIER.get(lang, lang)
        d = os.path.join(RES, 'values' + ('-' + q if q else ''))
        os.makedirs(d, exist_ok=True)
        out = ['<?xml version="1.0" encoding="utf-8"?>', '<!-- Generated by tools/strings.py (all languages share the same keys): change texts there or in tools/strings/. -->', '<resources>']
        for k in S:
            v = texts[k]
            fmt = ' formatted="false"' if ('%' in v and '%1$' not in v) else ''
            out.append(f'    <string name="{k}"{fmt}>{esc(v)}</string>')
        for k in ARR:
            out.append(f'    <string-array name="{k}">' + ''.join(f'<item>{esc(x)}</item>' for x in arrays[k]) + '</string-array>')
        out.append('</resources>')
        open(os.path.join(d, 'strings.xml'), 'w', encoding='utf-8').write('\n'.join(out) + '\n')
    print('keys', len(S), 'languages', len(all_langs))
